fn split_and_append(list: &Vec<i32>, n: usize) -> Vec<i32> {
    let len = list.len();
    // Preconditions: list is non-empty and 0 < n < len
    assert!(len > 0, "The input list must be non-empty");
    assert!(n > 0 && n < len, "Index n must be strictly between 0 and list.len()");

    // Allocate a new vector with the same capacity as the original list
    let mut new_list = Vec::with_capacity(len);

    // First, append elements from index n to the end
    new_list.extend_from_slice(&list[n..]);

    // Then, append elements from the start up to index n
    new_list.extend_from_slice(&list[..n]);

    new_list
}

